/**
 * @brief uart init
 *
 * @param[in] port_id: uart port id, id index starts at 0
 *                     in linux platform,
 *                         high 16 bits aslo means uart type,
 *                                   it's value must be one of the TUYA_UART_TYPE_E type
 *                         the low 16bit - means uart port id
 *                         you can input like this TUYA_UART_PORT_ID(TUYA_UART_SYS, 2)
 * @param[in] cfg: uart config
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_uart_init(TUYA_UART_NUM_E port_id, TUYA_UART_BASE_CFG_T *cfg)
{
    // --- BEGIN: user implements ---

    if (cfg == NULL) {
        return OPRT_INVALID_PARM;
    }
    if (!uart_port_supported(port_id) || !uart_config_supported(cfg)) {
        return OPRT_NOT_SUPPORTED;
    }

    taskENTER_CRITICAL();
    if (s_uart.initializing != pdFALSE || s_uart.initialized != pdFALSE || s_uart.stopping != pdFALSE) {
        taskEXIT_CRITICAL();
        return OPRT_INIT_MORE_THAN_ONCE;
    }
    s_uart.initializing = pdTRUE;
    taskEXIT_CRITICAL();

    StreamBufferHandle_t stream = xStreamBufferCreate(UART_RX_STREAM_SIZE, 1U);
    SemaphoreHandle_t    data_ready = xSemaphoreCreateBinary();
    SemaphoreHandle_t    callback_lock = xSemaphoreCreateMutex();
    SemaphoreHandle_t    worker_exited = xSemaphoreCreateBinary();
    TaskHandle_t         worker = NULL;

    if (stream == NULL || data_ready == NULL || callback_lock == NULL || worker_exited == NULL) {
        if (stream != NULL) {
            vStreamBufferDelete(stream);
        }
        if (data_ready != NULL) {
            vSemaphoreDelete(data_ready);
        }
        if (callback_lock != NULL) {
            vSemaphoreDelete(callback_lock);
        }
        if (worker_exited != NULL) {
            vSemaphoreDelete(worker_exited);
        }
        taskENTER_CRITICAL();
        s_uart.initializing = pdFALSE;
        taskEXIT_CRITICAL();
        return OPRT_MALLOC_FAILED;
    }

    if (xTaskCreate(uart_rx_worker, "uart0_rx", UART_RX_TASK_STACK, NULL, UART_RX_TASK_PRIO, &worker) != pdPASS) {
        vStreamBufferDelete(stream);
        vSemaphoreDelete(data_ready);
        vSemaphoreDelete(callback_lock);
        vSemaphoreDelete(worker_exited);
        taskENTER_CRITICAL();
        s_uart.initializing = pdFALSE;
        taskEXIT_CRITICAL();
        return OPRT_MALLOC_FAILED;
    }

    taskENTER_CRITICAL();
    s_uart.stream = stream;
    s_uart.data_ready = data_ready;
    s_uart.callback_lock = callback_lock;
    s_uart.worker_exited = worker_exited;
    s_uart.worker = worker;
    s_uart.callback = NULL;
    s_uart.rx_bytes = 0U;
    s_uart.rx_stream_dropped = 0U;
    s_uart.rx_overrun_errors = 0U;
    s_uart.rx_frame_errors = 0U;
    s_uart.rx_noise_errors = 0U;
    s_uart.rx_parity_errors = 0U;
    s_uart.rx_callback_count = 0U;
    s_uart.stopping = pdFALSE;
    s_uart.initialized = pdTRUE;
    s_uart.initializing = pdFALSE;
    /* Keep RX service active for read()/wait_for_data() even before callback registration. */
    usart_interrupt_enable(GD32H77X_CONSOLE_USART, USART_INT_RBNE);
    usart_interrupt_enable(GD32H77X_CONSOLE_USART, USART_INT_ERR);
    NVIC_ClearPendingIRQ(GD32H77X_CONSOLE_IRQn);
    NVIC_SetPriority(GD32H77X_CONSOLE_IRQn, 6U);
    NVIC_EnableIRQ(GD32H77X_CONSOLE_IRQn);
    taskEXIT_CRITICAL();

    /* Console clock, pins, and 115200 8N1 TX/RX are platform-initialized. */
    return OPRT_OK;
    // --- END: user implements ---
}

/**
 * @brief uart deinit
 *
 * @param[in] port_id: uart port id, id index starts at 0
 *                     in linux platform,
 *                         high 16 bits aslo means uart type,
 *                                   it's value must be one of the TUYA_UART_TYPE_E type
 *                         the low 16bit - means uart port id
 *                         you can input like this TUYA_UART_PORT_ID(TUYA_UART_SYS, 2)
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_uart_deinit(TUYA_UART_NUM_E port_id)
{
    // --- BEGIN: user implements ---

    if (!uart_port_supported(port_id)) {
        return OPRT_NOT_SUPPORTED;
    }
    if (xPortIsInsideInterrupt() != pdFALSE) {
        return OPRT_NOT_SUPPORTED;
    }

    taskENTER_CRITICAL();
    if (s_uart.initialized == pdFALSE || s_uart.stopping != pdFALSE) {
        taskEXIT_CRITICAL();
        return OPRT_RESOURCE_NOT_READY;
    }
    s_uart.stopping = pdTRUE;
    usart_interrupt_disable(GD32H77X_CONSOLE_USART, USART_INT_RBNE);
    usart_interrupt_disable(GD32H77X_CONSOLE_USART, USART_INT_ERR);
    NVIC_DisableIRQ(GD32H77X_CONSOLE_IRQn);
    NVIC_ClearPendingIRQ(GD32H77X_CONSOLE_IRQn);
    taskEXIT_CRITICAL();

    /* Serialize with any callback already running before TAL frees its RX ring. */
    (void)xSemaphoreTake(s_uart.callback_lock, portMAX_DELAY);
    s_uart.callback = NULL;
    xSemaphoreGive(s_uart.callback_lock);
    xTaskNotifyGive(s_uart.worker);
    (void)xSemaphoreTake(s_uart.worker_exited, portMAX_DELAY);

    vTaskDelete(s_uart.worker);
    vStreamBufferDelete(s_uart.stream);
    vSemaphoreDelete(s_uart.data_ready);
    vSemaphoreDelete(s_uart.callback_lock);
    vSemaphoreDelete(s_uart.worker_exited);

    taskENTER_CRITICAL();
    s_uart.stream = NULL;
    s_uart.data_ready = NULL;
    s_uart.callback_lock = NULL;
    s_uart.worker_exited = NULL;
    s_uart.worker = NULL;
    s_uart.initialized = pdFALSE;
    s_uart.stopping = pdFALSE;
    taskEXIT_CRITICAL();

    /* Leave the board console enabled for logging; only RX interrupt delivery stops. */
    return OPRT_OK;
    // --- END: user implements ---
}

/**
 * @brief uart write data
 *
 * @param[in] port_id: uart port id, id index starts at 0
 *                     in linux platform,
 *                         high 16 bits aslo means uart type,
 *                                   it's value must be one of the TUYA_UART_TYPE_E type
 *                         the low 16bit - means uart port id
 *                         you can input like this TUYA_UART_PORT_ID(TUYA_UART_SYS, 2)
 * @param[in] data: write buff
 * @param[in] len:  buff len
 *
 * @return return > 0: number of data written; return <= 0: write errror
 */
int tkl_uart_write(TUYA_UART_NUM_E port_id, void *buff, uint16_t len)
{
    // --- BEGIN: user implements ---

    if (!uart_port_supported(port_id)) {
        return OPRT_NOT_SUPPORTED;
    }
    if (buff == NULL && len != 0U) {
        return OPRT_INVALID_PARM;
    }
    if (len == 0U) {
        return 0;
    }
    if (s_uart.initialized == pdFALSE || xPortIsInsideInterrupt() != pdFALSE) {
        return OPRT_RESOURCE_NOT_READY;
    }

    const char *bytes = (const char *)buff;
    uint16_t    sent = 0U;
    while (sent < len) {
        uint16_t chunk = (uint16_t)(len - sent);
        if (chunk > UART_TX_CHUNK_SIZE) {
            chunk = UART_TX_CHUNK_SIZE;
        }
        gd32h77x_platform_log_write(bytes + sent, chunk);
        sent = (uint16_t)(sent + chunk);
    }
    return (int)sent;
    // --- END: user implements ---
}

/**
 * @brief enable uart rx interrupt and regist interrupt callback
 *
 * @param[in] port_id: uart port id, id index starts at 0
 *                     in linux platform,
 *                         high 16 bits aslo means uart type,
 *                                   it's value must be one of the TUYA_UART_TYPE_E type
 *                         the low 16bit - means uart port id
 *                         you can input like this TUYA_UART_PORT_ID(TUYA_UART_SYS, 2)
 * @param[in] rx_cb: receive callback
 *
 * @return none
 */
void tkl_uart_rx_irq_cb_reg(TUYA_UART_NUM_E port_id, TUYA_UART_IRQ_CB rx_cb)
{
    // --- BEGIN: user implements ---

    if (!uart_port_supported(port_id) || s_uart.initialized == pdFALSE || xPortIsInsideInterrupt() != pdFALSE) {
        return;
    }

    if (xSemaphoreTake(s_uart.callback_lock, portMAX_DELAY) != pdTRUE) {
        return;
    }
    BaseType_t callback_enabled = pdFALSE;
    taskENTER_CRITICAL();
    if (s_uart.initialized != pdFALSE && s_uart.stopping == pdFALSE) {
        s_uart.callback = rx_cb;
        if (rx_cb != NULL) {
            NVIC_ClearPendingIRQ(GD32H77X_CONSOLE_IRQn);
            usart_interrupt_enable(GD32H77X_CONSOLE_USART, USART_INT_RBNE);
            usart_interrupt_enable(GD32H77X_CONSOLE_USART, USART_INT_ERR);
            NVIC_SetPriority(GD32H77X_CONSOLE_IRQn, 6U);
            NVIC_EnableIRQ(GD32H77X_CONSOLE_IRQn);
            callback_enabled = pdTRUE;
        }
    }
    taskEXIT_CRITICAL();

    /* Keep deinit from deleting worker/stream resources until this notify ends. */
    if (callback_enabled != pdFALSE && xStreamBufferBytesAvailable(s_uart.stream) != 0U) {
        xTaskNotifyGive(s_uart.worker);
    }
    xSemaphoreGive(s_uart.callback_lock);
    // --- END: user implements ---
}

