/**
 * @brief wait for uart data
 *
 * @param[in] port_id: uart port id, id index starts at 0
 *                     in linux platform,
 *                         high 16 bits aslo means uart type,
 *                                   it's value must be one of the TUYA_UART_TYPE_E type
 *                         the low 16bit - means uart port id
 *                         you can input like this TUYA_UART_PORT_ID(TUYA_UART_SYS, 2)
 * @param[in] timeout_ms: the max wait time, unit is millisecond
 *                        -1 : block indefinitely
 *                        0  : non-block
 *                        >0 : timeout in milliseconds
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_uart_wait_for_data(TUYA_UART_NUM_E port_id, int timeout_ms)
{
    // --- BEGIN: user implements ---

    if (!uart_port_supported(port_id)) {
        return OPRT_NOT_SUPPORTED;
    }
    if (timeout_ms < -1) {
        return OPRT_INVALID_PARM;
    }
    if (s_uart.initialized == pdFALSE || xPortIsInsideInterrupt() != pdFALSE) {
        return OPRT_RESOURCE_NOT_READY;
    }

    TickType_t start = xTaskGetTickCount();
    TickType_t limit = timeout_ms < 0 ? portMAX_DELAY : gd32h77x_timeout_ticks((uint32_t)timeout_ms);
    for (;;) {
        if (xStreamBufferBytesAvailable(s_uart.stream) != 0U) {
            return OPRT_OK;
        }
        if (timeout_ms == 0) {
            return OPRT_TIMEOUT;
        }

        TickType_t wait_ticks = limit;
        if (timeout_ms > 0) {
            TickType_t elapsed = xTaskGetTickCount() - start;
            if (elapsed >= limit) {
                return OPRT_TIMEOUT;
            }
            wait_ticks = limit - elapsed;
        }
        if (xSemaphoreTake(s_uart.data_ready, wait_ticks) != pdTRUE && timeout_ms > 0) {
            return OPRT_TIMEOUT;
        }
    }
    // --- END: user implements ---
}

